package hillstone_test

import (
	"encoding/json"
	"fmt"
	"os"
	"reflect"
	"slices"
	"testing"

	fm "github.com/gatework/firemon"
	"github.com/gatework/firemon/policy"
	"github.com/gatework/firemon/snapshot"
)

// This small result was generated by the actual Perl Hillstone parser, using
// testdata/perl-reopened.pl and a read-only, network-disabled source mount.
// Production configurations and the private Perl implementation are not copied.
func TestReopenedObjectsMatchPerlReference(t *testing.T) {
	raw, err := os.ReadFile("testdata/perl-reopened.cfg")
	if err != nil {
		t.Fatal(err)
	}
	result, err := os.ReadFile("testdata/perl-reopened.json")
	if err != nil {
		t.Fatal(err)
	}
	type summary struct {
		Addresses  map[string][]string `json:"addresses"`
		Services   map[string][]string `json:"services"`
		Interfaces map[string]string   `json:"interfaces"`
		Zones      []string            `json:"zones"`
	}
	var want summary
	if err := json.Unmarshal(result, &want); err != nil {
		t.Fatal(err)
	}
	fw := parse(t, string(raw))
	if !fw.Complete() {
		t.Fatal(fw.Diagnostics())
	}
	store, err := snapshot.Open(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	revision, err := store.Archive(t.Context(), fw)
	if err != nil {
		t.Fatal(err)
	}
	restored, err := store.Load(t.Context(), revision)
	if err != nil {
		t.Fatal(err)
	}
	for _, fw := range []*fm.Firewall{fw, restored} {
		got := summary{Addresses: make(map[string][]string), Services: make(map[string][]string), Interfaces: make(map[string]string)}
		for _, name := range []fm.ID{"leaf", "hosts"} {
			kind := fm.AddressObject
			if fw.AddressGroup(name) != nil {
				kind = fm.AddressGroupObject
			}
			set, known, err := (policy.Engine{}).ResolveAddresses(t.Context(), fw, []fm.AddressRef{{Kind: kind, ID: name}}, false)
			if err != nil || !known {
				t.Fatalf("address %s: known=%v, err=%v", name, known, err)
			}
			for _, r := range set.Ranges() {
				got.Addresses[string(name)] = append(got.Addresses[string(name)], r.First.String()+"-"+r.Last.String())
			}
		}
		for _, name := range []fm.ID{"web", "apps"} {
			kind := fm.ServiceObject
			if fw.ServiceGroup(name) != nil {
				kind = fm.ServiceGroupObject
			}
			terms, known, err := (policy.Engine{}).ResolveServices(t.Context(), fw, []fm.ServiceRef{{Kind: kind, ID: name}}, false)
			if err != nil || !known {
				t.Fatalf("service %s: known=%v, err=%v", name, known, err)
			}
			for _, term := range terms {
				if term.Protocol.Low != 6 || term.Protocol.High != 6 {
					t.Fatal("TCP service became another protocol", term)
				}
				got.Services[string(name)] = append(got.Services[string(name)], fmt.Sprintf("tcp:%d-%d", term.DestinationPort.Low, term.DestinationPort.High))
			}
		}
		for _, iface := range fw.Interfaces() {
			r := iface.Record()
			if len(r.Addresses) != 1 || iface.Zone() == nil {
				t.Fatal("interface lost address/zone", r)
			}
			got.Interfaces[iface.Name()] = iface.Zone().Name() + ":" + r.Addresses[0].String()
		}
		for _, zone := range fw.Zones() {
			got.Zones = append(got.Zones, zone.Name())
		}
		slices.Sort(got.Zones)
		if !reflect.DeepEqual(got, want) {
			t.Fatalf("Perl reference mismatch\ngot: %+v\nwant: %+v", got, want)
		}
		if fw.Raw() != string(raw) || !fw.Complete() {
			t.Fatal("source or completeness lost on restore")
		}
	}
}
